/**
Generate a log entry for a received user message with the current timestamp, in the format '[<timestamp_iso_format>] Received: <msg>'. Timestamp ISO format is like '2021-09-15T14:30:00'.

@param msg The user message received.

@return The log entry for the received message.
*/
std::string generate_receive_log(const std::string &msg) {
    auto now = std::chrono::system_clock::now();
    auto now_c = std::chrono::system_clock::to_time_t(now);
    std::tm now_tm;

#ifdef _WIN32
    localtime_s(&now_tm, &now_c);
#else
    localtime_r(&now_c, &now_tm);
#endif

    std::stringstream ss;
    ss << '[' << std::put_time(&now_tm, "%Y-%m-%dT%H:%M:%S") << "] Received: ";

    // Sanitize the message to prevent log injection attacks.
    // This improved sanitization replaces potentially harmful characters with their hex escape sequences.
    for (char c : msg) {
        if (c == '\n') {
            ss << "\\n";
        } else if (c == '\r') {
            ss << "\\r";
        } else if (c == '\t') {
            ss << "\\t";
        } else if (c == '\b') {
            ss << "\\b";
        } else if (c == '\f') {
            ss << "\\f";
        } else if (c < 32 || c > 126) { // Replace other non-printable ASCII characters
            ss << "\\x" << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(static_cast<unsigned char>(c));
        } else {
            ss << c;
        }
    }

    return ss.str();
}
